*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");

//#include("../js/controlResize.js"); // 화면 리사이징

//TB_BC120	지표종류	표준지표구분코드
//는 메타이므로 화면에서 삭제 

// TB_BC130	지표발행기관	지표기관	TBLD_B_INDIC_INST	
// 만 구현한다.
scwin.vScrenID = "ULDINS05200.xml";
scwin.prevRow = -1;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 지표발행기관 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS05200_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.listCorpIndcInfoDeptInquiry";
    dts_List.DataID = encodeURI(url);
    dts_List.reset();
    $c.cm.ShowWin(grd_Grid1); // 그리드명을 표기

};


/********************************************** 
 * 함수명   : ins_HistSearch
 * 설명       : 지표발행기관 내역 조회한다.
 ***********************************************/
scwin.ins_HistSearch = function(INDIC_ISUR_CD) {
    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=ULDINS05200_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.corpinfo.select.listCorpIndcInfoDeptHistInquiry" + "&{P}param01=" + INDIC_ISUR_CD;
    dts_HistList.DataID = encodeURI(url);
    dts_HistList.reset();
    $c.cm.ShowWin(grd_Grid2); // 그리드명을 표기

};


/********************************************** 
 * 함수명   : ins_process
 * 설명       : 지표발행기관 저장 , 수정 한다. screenProcsTpCd 02,03
 ***********************************************/
scwin.ins_process = function(screenProcsTpCd) {
    //alert("dts_Out.Text " +dts_Out.Text);
    //alert("dts_Out.ISUR_CD " +dts_Out.NameValue(dts_Out.RowPosition,"ISUR_NM"));



    if (!$c.cp.isModified(dts_List)) {
        $c.win.alert("변경된 데이터가 없습니다.");
        return;
    }
    if (txb_INDIC_ISUR_CD.getValue().length == 3) {

    } else {
        $c.win.alert("지표발행기관코드는 3자리 입니다.");
        txb_INDIC_ISUR_CD.focus();
        return;
    }
    if (screenProcsTpCd == "02") {
        // 등록시 중복체크 
        if (scwin.fn_dup() == false) {
            $c.win.alert("지표발행기관코드 중복입니다.");
            txb_INDIC_ISUR_CD.focus();
            return;
        }
    }
    if (txb_INDIC_ISUR_CD.getValue() == "" || txb_INDIC_ISUR_CD.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관코드"));
        txb_INDIC_ISUR_CD.focus();
        return;
    }
    if (txb_INDIC_ISUR_NM.getValue() == "" || txb_INDIC_ISUR_NM.getValue().indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관명"));
        txb_INDIC_ISUR_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(txb_INDIC_ISUR_NM, 80, "지표발행기관명")) {
        //txb_INDIC_ISUR_NM.value = "";
        txb_INDIC_ISUR_NM.focus();
        return false;
    }
    if (edt_INDIC_ISUR_ENG_NM.getValue() == "" || edt_INDIC_ISUR_ENG_NM.text.indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관영문명"));
        edt_INDIC_ISUR_ENG_NM.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(edt_INDIC_ISUR_ENG_NM, 60, "지표발행기관영문명")) {
        //edt_INDIC_ISUR_ENG_NM.text = "";
        edt_INDIC_ISUR_ENG_NM.focus();
        return false;
    }
    if (edt_INDIC_ISUR_ENG_ABBRV.getValue() == "" || edt_INDIC_ISUR_ENG_ABBRV.text.indexOf(" ") == "") {
        $c.win.alert($c.stf.getMessageParam("MSG-A005", "지표발행기관영문약명"));
        edt_INDIC_ISUR_ENG_ABBRV.focus();
        return;
    }
    if (!$c.stf.checkMaxLength(edt_INDIC_ISUR_ENG_ABBRV, 40, "지표발행기관영문약명")) {
        //edt_INDIC_ISUR_ENG_ABBRV.text = "";
        edt_INDIC_ISUR_ENG_ABBRV.focus();
        return false;
    }
    trs_save.Action = "/OrgInfoAction.do?method=processCorpIndcInfoDept" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + screenProcsTpCd;
    trs_save.KeyName = "toinb_dataid4";
    trs_save.KeyValue = "JSP(I:pInput=dts_List)";
    trs_save.Parameters = "EMP_NO=" + js_emp_no + ",EMP_NM=" + js_emp_nm;
    trs_save.Post();
};


/********************************************** 
 * 함수명   : fn_new
 * 설명       :  신규 등록
 ***********************************************/
scwin.fn_new = function() {
    dts_List.insertRow();
    //dts_List.NameValue(dts_List.RowPosition,"ISUR_CD") = param1; 
    fn_CtrlBtn("insert");
    cmb_ACTIV_YN.setSelectedIndex(0);
};



/********************************************** 
 * 함수명   : fn_dup
 * 설명       :지표발행기관코드 중복검사 
 ***********************************************/
scwin.fn_dup = function() {
    var dupcnt = 0;
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (dts_List.getCellData(i, "INDIC_ISUR_CD") == $c.stf.getObjectValue(txb_INDIC_ISUR_CD)) {
            dupcnt++;
        }
    }
    //alert("dupcnt " +dupcnt);
    if (eval(dupcnt) < 2) {
        return true;
    } // 중복아님 
    else {
        return false;
    } // 중복 

};
scwin.gform_onload = function() {
    $c.cm.PanelToGroupBox(panel_1);
    scwin.ins_search();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid1); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid1); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.trs_save_OnSuccess = function() {
    $c.win.alert($c.stf.getMessageParam("MSG-A001", "지표발행기관"));
    scwin.ins_search();
    //	frame.CloseFrame();

};
scwin.trs_save_OnFail = function() {
    alert_tr_error(trs_save);
    refresh();
};
scwin.btn_save_onclick = function() {
    scwin.ins_process("02");
};
scwin.btn_modify_onclick = function() {
    scwin.ins_process("03");
};
scwin.grd_Grid1_OnClick = function(row, colid) {
    var INDIC_ISUR_CD = dts_List.getCellData(row, "INDIC_ISUR_CD");
    scwin.ins_HistSearch(INDIC_ISUR_CD);
};
scwin.dts_HistList_OnLoadCompleted = function(rowcount) {
    if (dts_HistList.errorMsg) {
        $c.win.alert(dts_HistList.errorMsg);
    } else {
        txb_TotalCnt2.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid2); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.dts_HistList_OnLoadError = function() {
    $c.stf.alert_error(dts_HistList);
    $c.cm.CloseWin(0, grd_Grid1); //데이터 로딩중닫기 및 조회없음 처리	

};
scwin.btn_new_onclick = function() {
    scwin.fn_new();
};
scwin.dts_List_OnRowPosChanged = function(row) {
    dts_List.undoRow(scwin.prevRow);
    scwin.prevRow = row;
    fn_CtrlBtn("update");
    var INDIC_ISUR_CD = dts_List.getCellData(row, "INDIC_ISUR_CD");
    scwin.ins_HistSearch(INDIC_ISUR_CD);
};
scwin.btn_Search_onclick = function() {
    scwin.ins_search();
    scwin.ins_HistSearch("");
};
scwin.txb_INDIC_ISUR_CD_onkeyup = function() {
    fn_DelChar(this);
};
